    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new UserInvitation(
            uid: 'one',
            tenant: new TenantRef('one'),
            email: 'one',
            roles: 'one',
            invitedBy: new UserRef('one'),
            tokenHash: 'one',
            metadataJson: 'one',
            status: UserInvitationStatusOptions::PENDING,
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            expiredAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            acceptedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            acceptedBy: new UserRef('one'),
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->createNewInstance();
        $calculated = UserInvitation::calculatedFields();

        // @Assert
        $this->assertEquals([], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTenant(), $other->getTenant());
        $this->assertTrue($one->isTenantChanged());
        $this->assertEquals($one->getEmail(), $other->getEmail());
        $this->assertTrue($one->isEmailChanged());
        $this->assertEquals($one->getRoles(), $other->getRoles());
        $this->assertTrue($one->isRolesChanged());
        $this->assertEquals($one->getInvitedBy(), $other->getInvitedBy());
        $this->assertTrue($one->isInvitedByChanged());
        $this->assertEquals($one->getTokenHash(), $other->getTokenHash());
        $this->assertTrue($one->isTokenHashChanged());
        $this->assertEquals($one->getMetadataJson(), $other->getMetadataJson());
        $this->assertTrue($one->isMetadataJsonChanged());
        $this->assertEquals($one->getStatus(), $other->getStatus());
        $this->assertTrue($one->isStatusChanged());
        $this->assertEquals($one->getCreatedAt(), $other->getCreatedAt());
        $this->assertTrue($one->isCreatedAtChanged());
        $this->assertEquals($one->getExpiredAt(), $other->getExpiredAt());
        $this->assertTrue($one->isExpiredAtChanged());
        $this->assertEquals($one->getAcceptedAt(), $other->getAcceptedAt());
        $this->assertTrue($one->isAcceptedAtChanged());
        $this->assertEquals($one->getAcceptedBy(), $other->getAcceptedBy());
        $this->assertTrue($one->isAcceptedByChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
