        $this->assertTrue($one->isTokenHashChanged($base));
        $this->assertEquals($one->getMetadataJson(), $other->getMetadataJson());
        $this->assertTrue($one->isMetadataJsonChanged($base));
        $this->assertEquals($one->getStatus(), $other->getStatus());
