    public function test_json_compare(): void
    {
        // @Arrange
        $one = new UserInvitation(
            uid: 'one',
            tenant: new TenantRef('one'),
            email: 'one',
            roles: 'one',
            invitedBy: new UserRef('one'),
            tokenHash: 'one',
            metadataJson: 'one',
            status: UserInvitationStatusOptions::PENDING,
            createdAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            expiredAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            acceptedAt: (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')),
            acceptedBy: new UserRef('one'),
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['tenant']['$ref']);
        $this->assertEquals('one', $json['email']);
        $this->assertEquals('one', $json['roles']);
        $this->assertEquals('one', $json['invitedBy']['$ref']);
        $this->assertEquals('one', $json['tokenHash']);
        $this->assertEquals(UserInvitationStatusOptions::PENDING, $json['status']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['createdAt']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['expiredAt']);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $json['acceptedAt']);
        $this->assertEquals('one', $json['acceptedBy']['$ref']);
        $this->assertEquals(1, $json['version']);
    }
